// MarketplaceServiceServer is the server API for MarketplaceService service.
// All implementations must embed UnimplementedMarketplaceServiceServer
// for forward compatibility.
//
// MarketplaceService owns provider (tutor/guide) profiles, subjects,
// availability, bookings, booking messages, reviews, blocks and in-app
// notifications. Timestamps are unix seconds; money is in minor units of the
// provider's campus currency.
type MarketplaceServiceServer interface {
	ListSubjects(context.Context, *ListSubjectsRequest) (*ListSubjectsResponse, error)
	GetSubjects(context.Context, *GetSubjectsRequest) (*ListSubjectsResponse, error)
	CreateSubject(context.Context, *CreateSubjectRequest) (*Subject, error)
	SaveProviderProfile(context.Context, *SaveProviderProfileRequest) (*ProviderProfile, error)
	SetProviderStatus(context.Context, *SetProviderStatusRequest) (*ProviderProfile, error)
	GetProviderProfile(context.Context, *GetProviderProfileRequest) (*ProviderProfile, error)
	ListUserProviderProfiles(context.Context, *UserRequest) (*ProviderProfileList, error)
	SearchProviders(context.Context, *SearchProvidersRequest) (*SearchProvidersResponse, error)
	// Keeps the denormalised name/avatar on a user's profiles in sync.
	SyncUserCard(context.Context, *SyncUserCardRequest) (*Empty, error)
	// Keeps the timezone copied onto a campus's profiles in sync after an admin edit.
	SyncCampusTimezone(context.Context, *SyncCampusTimezoneRequest) (*Empty, error)
	SetAvailability(context.Context, *SetAvailabilityRequest) (*AvailabilityResponse, error)
	GetAvailability(context.Context, *UserRequest) (*AvailabilityResponse, error)
	GetOpenSlots(context.Context, *GetOpenSlotsRequest) (*GetOpenSlotsResponse, error)
	CreateBooking(context.Context, *CreateBookingRequest) (*Booking, error)
	GetBooking(context.Context, *GetBookingRequest) (*Booking, error)
	ListBookings(context.Context, *ListBookingsRequest) (*ListBookingsResponse, error)
	TransitionBooking(context.Context, *TransitionBookingRequest) (*Booking, error)
	ListMessages(context.Context, *ListMessagesRequest) (*ListMessagesResponse, error)
	SendMessage(context.Context, *SendMessageRequest) (*Message, error)
	CreateReview(context.Context, *CreateReviewRequest) (*Review, error)
	ListReviews(context.Context, *ListReviewsRequest) (*ListReviewsResponse, error)
	GetReview(context.Context, *GetReviewRequest) (*Review, error)
	SetReviewHidden(context.Context, *SetReviewHiddenRequest) (*Review, error)
	ListNotifications(context.Context, *ListNotificationsRequest) (*ListNotificationsResponse, error)
	MarkNotificationsRead(context.Context, *MarkNotificationsReadRequest) (*Empty, error)
	Notify(context.Context, *NotifyRequest) (*Empty, error)
	BlockUser(context.Context, *BlockRequest) (*Empty, error)
	UnblockUser(context.Context, *BlockRequest) (*Empty, error)
	ListBlocks(context.Context, *UserRequest) (*ListBlocksResponse, error)
	// Career mentors: feedback after a mock interview, and resume reviews.
	SaveInterviewFeedback(context.Context, *SaveInterviewFeedbackRequest) (*InterviewFeedback, error)
	GetInterviewFeedback(context.Context, *GetBookingRequest) (*InterviewFeedback, error)
	CreateResumeReview(context.Context, *CreateResumeReviewRequest) (*ResumeReview, error)
	GetResumeReview(context.Context, *GetResumeReviewRequest) (*ResumeReview, error)
	ListResumeReviews(context.Context, *ListResumeReviewsRequest) (*ListResumeReviewsResponse, error)
	TransitionResumeReview(context.Context, *TransitionResumeReviewRequest) (*ResumeReview, error)
	DeliverResumeReview(context.Context, *DeliverResumeReviewRequest) (*ResumeReview, error)
	// Hands the gateway the uploads of long-closed resume reviews to delete,
	// and forgets them.
	ClaimExpiredResumeFiles(context.Context, *Empty) (*FileKeys, error)
	// Live interview rooms. OpenRoom checks who may join and when; the rest
	// hold what the interview produced.
	OpenRoom(context.Context, *RoomRequest) (*RoomAccess, error)
	GetRoom(context.Context, *RoomRequest) (*Room, error)
	SaveRoom(context.Context, *SaveRoomRequest) (*Empty, error)
	RecordPresence(context.Context, *PresenceEvent) (*Empty, error)
	AddMentorNote(context.Context, *AddMentorNoteRequest) (*MentorNote, error)
	ListMentorNotes(context.Context, *RoomRequest) (*MentorNotes, error)
	DeleteMentorNote(context.Context, *DeleteMentorNoteRequest) (*Empty, error)
	// The mentors' question bank.
	SaveQuestion(context.Context, *SaveQuestionRequest) (*Question, error)
	ListQuestions(context.Context, *ListQuestionsRequest) (*ListQuestionsResponse, error)
	GetQuestion(context.Context, *GetQuestionRequest) (*Question, error)
	DeleteQuestion(context.Context, *GetQuestionRequest) (*Empty, error)
	// Placement prep hub and progress.
	GetProviderInsights(context.Context, *ProviderInsightsRequest) (*ProviderInsights, error)
	AvailableSoon(context.Context, *AvailableSoonRequest) (*AvailableSoonResponse, error)
	MentorCompanies(context.Context, *Empty) (*CompanyCounts, error)
	GetProgress(context.Context, *UserRequest) (*Progress, error)
	Stats(context.Context, *Empty) (*MarketplaceStats, error)
	// The choices the service accepts, with display labels.
	GetCatalog(context.Context, *Empty) (*MarketplaceCatalog, error)
	mustEmbedUnimplementedMarketplaceServiceServer()
}

